import { useState, useEffect, useRef } from 'react';
import { searchCharacters } from './BangumiRequest';
import styles from './styles/InputStyles.module.css';

function SearchDropdown() {
    const [inputTerm, setInputTerm] = useState('');
    const [results, setResults] = useState({value : [],completed : false});
    const [isLoading, setIsLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef(null);

    // 点击外部关闭下拉框
    useEffect(() => {
        const handleClickOutside = (event) => {
        if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
            setIsOpen(false);
        }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // 搜索函数
    const handleSearch = () => {
        if (!inputTerm.trim()) {
        setResults({value : [], completed : true});
        return;
        }

        setIsLoading(true);
        setIsOpen(true);
        setResults({value : [], completd : false});

        searchCharacters(inputTerm)
        .then(response => {
            setResults({value : response.data, completed : true}); // 标记搜索已完成
            //console.log('搜索结果：',response,results.value,results.completed,typeof results.value,results.value.length);
        })
        .catch(error => {
            console.error('搜索失败:', error);
            setResults({value : [], completd : true}); // 即使出错也标记完成
        })
        .finally(() => {
            setIsLoading(false);
        });
    };

    return (
        <div className={styles.searchContainer} ref={dropdownRef}>
        <div className={styles.searchBox}>
            <input
            type="text"
            value={inputTerm}
            onChange={(e) => setInputTerm(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
            placeholder="输入角色名..."
            className={styles.searchInput}
            />
            <button
            onClick={handleSearch}
            disabled={isLoading}
            className={styles.searchButton}
            >
            {isLoading ? '搜索中...' : '搜索'}
            </button>
        </div>

        {/* 下拉框 - 根据状态精确控制显示内容 */}
        {isOpen && (
            <div className={styles.dropdown}>
            {isLoading ? (
                <div className={styles.dropdownItem}>加载中...</div>
            ) : results.completed ? ( // 只有搜索完成后再判断结果
                (console.log(results) && false) || (typeof results.value == typeof [] && results.value.length > 0) ? (
                results.value.map(item => (
                    <div
                    key={item.id}
                    className={styles.dropdownItem}
                    onClick={() => {
                        setInputTerm(item.name);
                        setIsOpen(false);
                    }}
                    >
                    {item.infobox.value}
                    </div>
                ))
                ) : (
                <div className={styles.dropdownItem}>未找到结果</div>
                )
            ) : null}
            </div>
        )}
        </div>
    );
}

export default SearchDropdown;
